  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	    private static final int NEGATIVE_CYCLE_MARKER = -1;
  6	    private static final int FROM_INDEX = 0;
  7	    private static final int TO_INDEX = 1;
  8	    private static final int WEIGHT_INDEX = 2;
  9	    private static final int EDGE_FIELD_COUNT = 3;
 10	
 11	    private BellmanFord() {
 12	    }
 13	
 14	    static int[] bellmanFord(int vertexCount, int[][] edgeData, int source) {
 15	        Graph graph = Graph.from(vertexCount, edgeData);
 16	        graph.validateSource(source);
 17	        return shortestPathsFrom(graph, source);
 18	    }
 19	
 20	    private static int[] shortestPathsFrom(Graph graph, int source) {
 21	        int[] distances = graph.initialDistances(source);
 22	
 23	        for (int pass = 0; pass < graph.relaxationPasses(); pass++) {
 24	            if (!graph.relaxEdges(distances)) {
 25	                break;
 26	            }
 27	        }
 28	
 29	        if (graph.hasReachableNegativeCycle(distances)) {
 30	            return negativeCycleResult();
 31	        }
 32	
 33	        return distances;
 34	    }
 35	
 36	    private static int[] negativeCycleResult() {
 37	        return new int[]{NEGATIVE_CYCLE_MARKER};
 38	    }
 39	
 40	    private static String formatDistances(int[] distances) {
 41	        StringBuilder output = new StringBuilder();
 42	        for (int distance : distances) {
 43	            output.append(distance).append(' ');
 44	        }
 45	
 46	        return output.toString();
 47	    }
 48	
 49	    private static final class Edge {
 50	        private final int from;
 51	        private final int to;
 52	        private final int weight;
 53	
 54	        private Edge(int from, int to, int weight) {
 55	            this.from = from;
 56	            this.to = to;
 57	            this.weight = weight;
 58	        }
 59	
 60	        private boolean isWithin(int vertexCount) {
 61	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 62	        }
 63	
 64	        private boolean relax(int[] distances) {
 65	            if (!canRelax(distances)) {
 66	                return false;
 67	            }
 68	
 69	            distances[to] = distances[from] + weight;
 70	            return true;
 71	        }
 72	
 73	        private boolean canRelax(int[] distances) {
 74	            return distances[from] != INF && distances[from] + weight < distances[to];
 75	        }
 76	    }
