 78	    private static final class Graph {
 79	        private final int vertexCount;
 80	        private final Edge[] edges;
 81	
 82	        private Graph(int vertexCount, Edge[] edges) {
 83	            this.vertexCount = vertexCount;
 84	            this.edges = edges;
 85	        }
 86	
 87	        private static Graph from(int vertexCount, int[][] edgeData) {
 88	            if (vertexCount < 0) {
 89	                throw new IllegalArgumentException("Vertex count cannot be negative");
 90	            }
 91	
 92	            if (edgeData == null) {
 93	                throw new IllegalArgumentException("Edges cannot be null");
 94	            }
 95	
 96	            Edge[] edges = new Edge[edgeData.length];
 97	            for (int i = 0; i < edgeData.length; i++) {
 98	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
 99	            }
100	
101	            return new Graph(vertexCount, edges);
102	        }
103	
104	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
105	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
106	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
107	            }
108	
109	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
110	            if (!edge.isWithin(vertexCount)) {
111	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
112	            }
113	
114	            return edge;
115	        }
116	
117	        private void validateSource(int source) {
118	            if (source < 0 || source >= vertexCount) {
119	                throw new IllegalArgumentException("Source vertex is out of range");
120	            }
121	        }
122	
123	        private int[] initialDistances(int source) {
124	            int[] distances = new int[vertexCount];
125	            Arrays.fill(distances, INF);
126	            distances[source] = 0;
127	            return distances;
128	        }
129	
130	        private int relaxationPasses() {
131	            return Math.max(0, vertexCount - 1);
132	        }
133	
134	        private boolean relaxEdges(int[] distances) {
135	            boolean changed = false;
136	
137	            for (Edge edge : edges) {
138	                if (edge.relax(distances)) {
139	                    changed = true;
140	                }
141	            }
142	
143	            return changed;
144	        }
145	
146	        private boolean hasReachableNegativeCycle(int[] distances) {
147	            for (Edge edge : edges) {
148	                if (edge.canRelax(distances)) {
149	                    return true;
150	                }
151	            }
152	
153	            return false;
154	        }
155	    }
156	
